import { SuAnDisarida } from '../tasarim/SuAnDisarida'
import { useDil } from '../../lib/dil'
import { yazi, olcek, bosluk, yuvarlak, golge, type Renk } from '../tasarim/tema'
import { useRenk, useStiller } from '../tasarim/tema-baglami'
import { MarkaYazisi } from '../tasarim/MarkaYazisi'
import { ALT_GEZINME_PAYI } from '../tasarim/AltGezinme'

/** Arama kutusunun basindaki buyutec. */
function BuyutecIkonu() {
  const renk = useRenk()

  return (
    <Svg width={18} height={18} viewBox="0 0 24 24">
      <Circle
        cx={11}
        cy={11}
        r={7}
        stroke={renk.metinIkincil}
        strokeWidth={2}
        fill="none"
      />
      <Path
        d="M16.5 16.5 21 21"
        stroke={renk.metinIkincil}
        strokeWidth={2}
        strokeLinecap="round"
    }
  }

  async function yenile() {
    setYenileniyor(true)
    await yukle()
    setYenileniyor(false)
  }

  return (
    <View style={stiller.kok}>
      {/* Marka EN USTTE, hemen altinda arama sutunu (kullanicinin
          istegi 2026-08-28). */}
      <View style={stiller.ustCubuk}>
        <MarkaYazisi genislik={88} />
      </View>

      {/* Instagram duzeni (kullanicinin gonderdigi referans): kenarliksiz
          DOLGULU kutu, solda buyutec, hemen yaninda sola dayali metin.
          Onceki hali beyaz zeminli-kenarlikliydi ve yazi ortaliydi. */}
      <View style={stiller.aramaKutusu}>
        <BuyutecIkonu />
        <TextInput
          style={stiller.aramaGirdisi}
          placeholder={t('anaSayfa.aramaYerTutucu')}
          placeholderTextColor={renk.metinIkincil}
          autoCapitalize="none"
          autoCorrect={false}
          value={arama}
          onChangeText={aramaDegisti}
          returnKeyType="search"
        />
      </View>

      {hata && <Text style={stiller.hata}>{hata}</Text>}

      {aramaAcik ? (
        <FlatList
          data={sonuclar}
          keyExtractor={(k) => k.id}
          contentContainerStyle={stiller.liste}
          keyboardShouldPersistTaps="handled"
          renderItem={({ item }) => (
            <KisiSatiri kisi={item} onSec={(k) => router.push(`/kullanici/${k.id}`)} />
          )}
          ListEmptyComponent={
            aramaDurumu ? <Text style={stiller.durum}>{aramaDurumu}</Text> : null
          }
        />
      ) : (
      <FlatList
        testID="akis-listesi"
        data={ogeler}
        keyExtractor={(o) => o.id}
        contentContainerStyle={stiller.liste}
        showsVerticalScrollIndicator={false}
        refreshing={yenileniyor}
        onRefresh={yenile}
        // Liste SONSUZ: sona yaklasinca bir sonraki sayfa iniyor.
        // Esik 0.6 - kullanici tam dibe varmadan yukleme basliyor,
        // boylece kaydirma bosluga carpmıyor.
        onEndReached={dahaYukle}
        onEndReachedThreshold={0.6}
        ListFooterComponent={
          dahaYukleniyor ? (
            <Text style={stiller.durum}>{t('ortak.yukleniyor')}</Text>
          ) : null
        }
        // "Su an disarida" seridi AKISLA BIRLIKTE kayiyor
        // (ListHeaderComponent), ekranin tepesine cakili degil:
        // referansta da kaydiriliyor ve cakili olsa akisa ayrilan
    color: renk.yikici,
  },

  kok: { flex: 1, backgroundColor: renk.zemin },

  // Marka ORTADA ve yukarida (kullanicinin istegi 2026-08-27:
  // "slooin yazisini biraz kucult ve yukari ortaya koy"). Onceden
  // sola dayaliydi ve 104 genisligindeydi.
  aramaKutusu: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: bosluk.s,
    marginHorizontal: bosluk.l,
    marginBottom: bosluk.m,
    // Kenarlik yok, dolgu var. Ton gun ayraclariyla ayni (#F6F1EB):
    // beyaz sayfada kendini belli ediyor ama dikkat cekmiyor.
    // Jetona gecti: koyu modda kremsi bir kutu beyaz bir delik gibi
    // duruyordu.
    backgroundColor: renk.turuncuZemin,
    borderRadius: yuvarlak.kart,
    paddingHorizontal: bosluk.m,
    paddingVertical: 11,
  },
  aramaGirdisi: {
    flex: 1,
    fontFamily: yazi.govde,
    fontSize: olcek.govde,
    color: renk.metin,
  },

  ustCubuk: {
    alignItems: 'center',
    paddingHorizontal: bosluk.sayfa,
    paddingTop: bosluk.xl,
    paddingBottom: bosluk.m,
  },

  hata: {
    fontFamily: yazi.govdeOrta,
    fontSize: olcek.kucuk,
    color: renk.yikici,
    paddingHorizontal: bosluk.sayfa,
    marginBottom: bosluk.s,
  },
  durum: {
    fontFamily: yazi.govde,
    fontSize: olcek.kucuk,
    color: renk.metinIkincil,
    paddingHorizontal: bosluk.sayfa,
  },

  // Kartlar TAM GENISLIK (kullanicinin istegi 2026-09-02): yatay dolgu
  // burada degil, kartin kendi icinde - yoksa kartin zemini kenara
  // ulasmiyor ve yine bir sinir gorunuyordu.
  liste: { paddingBottom: ALT_GEZINME_PAYI },

----KART
  buyukKapatYazi: { fontFamily: yazi.govde, fontSize: 34, color: '#FFFFFF', lineHeight: 38 },
  buyukFotograf: { width: '100%', height: '70%' },
  buyukAltyazi: { position: 'absolute', left: 0, right: 0, bottom: 0 },

  kart: {
    // REFERANS KARTI (2026-09-18): yuvarlak koseli, kenardan payli,
    // ince cerceveli beyaz kart. 2026-09-02'nin "tam genislik, yalnizca
    // alt cizgi" duzeni bu referansla degisti. Beyaz zeminde karti
    // gorunur kilan cerceve + hafif golge (2026-08-27 notu).
    backgroundColor: renk.yuzey,
    borderRadius: 20,
    borderWidth: 1,
    borderColor: renk.cizgi,
    // YANLARA UZATILDI (kullanicinin istegi 2026-09-18: "sutunlari saga
    // ve sola uzat"): pay sayfa payinin yarisi.
    marginHorizontal: bosluk.s,
    marginTop: bosluk.m,
    paddingHorizontal: bosluk.l,
    paddingVertical: bosluk.l,
    ...golge.kart,
  },
  kartUst: { flexDirection: 'row', alignItems: 'center', gap: bosluk.m },
  mekanSatiri: {
116:  zemin: '#FFFFFF',
122:  karsilamaZemini: '#FAF7F3',
124:  yuzey: '#FFFFFF',
138:  cizgi: '#DCD3C9',
262:  /** Yumusak zemin: turuncunun sicak, cok koyu hali. */
270:  zemin: '#121110',
271:  karsilamaZemini: '#171512',
277:  yuzey: '#1C1917',
