  // Yol kokun ALTINDA kalmak zorunda: "../" ile disari cikan istek 403.
  let p = path.resolve(kok, '.' + decodeURIComponent(req.url.split('?')[0]))
  if (p !== kok && !p.startsWith(kok + path.sep)) {
    res.writeHead(403)
    return res.end()
