import re
def oku(p): return open(p, encoding='utf-8').read()
def yaz(p, s): open(p, 'w', encoding='utf-8', newline='\n').write(s)

# ---- lib ----
p = 'lib/bag-listeleri.ts'
s = oku(p)
s = s.rstrip('\n') + """

/**
 * BASKASININ ARKADASLARI (2026-09-20): profil sayaclarindaki "Arkadas"
 * bolumu. Kapi sunucuda (`baskasinin_arkadaslari`): profil gizliyse
 * yalnizca arkadaslarina, engel varsa hic; liste pasif/engelli
 * kisileri eler. Avatar ikincil: okunamazsa bas harf.
 */
export async function baskasininArkadaslariniGetir(kullaniciId: string): Promise<BagKisi[]> {
  const { data, error } = await supabase.rpc('baskasinin_arkadaslari', { p_kullanici_id: kullaniciId })
  if (error) throw new Error(hataMetni(error))
  const satirlar = (data ?? []) as SunucuKisi[]
  const avatarlar = await avatarlariGetir(satirlar.map((s) => s.id)).catch(() => ({}) as Record<string, string | null>)
  return satirlar.map((satir) => ({
    id: satir.id,
    kullaniciAdi: satir.kullanici_adi,
    ad: satir.ad,
    avatarUrl: avatarlar[satir.id] ?? null,
  }))
}
"""
yaz(p, s)

# ---- sozluk ----
metin = {
    'tr': ("Henüz fotoğrafı yok", "Henüz arkadaşı yok"),
    'en': ("No photos yet", "No friends yet"),
    'de': ("Noch keine Fotos", "Noch keine Freunde"),
    'es': ("Aún no hay fotos", "Aún no tiene amigos"),
    'fr': ("Pas encore de photos", "Pas encore d’amis"),
    'ru': ("Фото пока нет", "Друзей пока нет"),
    'ar': ("لا صور بعد", "لا أصدقاء بعد"),
}
for dil, (foto, ark) in metin.items():
    p = f'lib/ceviriler/{dil}.ts'
    s = oku(p)
    m = re.search(r"(    yerYok: .*\n)", s)
    assert m, dil
    q = lambda t: ('"' + t + '"') if "'" in t or "’" in t else ("'" + t + "'")
    s = s.replace(m.group(1), m.group(1) + f"    fotografYok: {q(foto)},\n    arkadasYok: {q(ark)},\n", 1)
    yaz(p, s)

