import re
def oku(p): return open(p, encoding='utf-8').read()
def yaz(p, s): open(p, 'w', encoding='utf-8', newline='\n').write(s)

# ---------------- sozluk ----------------
S = {
 'tr': ("{{ad}}, {{mekan}}{{ek}} check-in yaptı.", "{{adlar}} ile birlikte"),
 'en': ("{{ad}} checked in at {{mekan}}{{ek}}.", "with {{adlar}}"),
 'de': ("{{ad}} hat bei {{mekan}}{{ek}} eingecheckt.", "zusammen mit {{adlar}}"),
 'es': ("{{ad}} hizo check-in en {{mekan}}{{ek}}.", "junto a {{adlar}}"),
 'fr': ("{{ad}} a fait un check-in à {{mekan}}{{ek}}.", "avec {{adlar}}"),
 'ru': ("{{ad}} отметился в {{mekan}}{{ek}}.", "вместе с {{adlar}}"),
 'ar': ("{{ad}} سجّل وصوله في {{mekan}}{{ek}}.", "مع {{adlar}}"),
}
for dil, (c, b) in S.items():
    p = f'lib/ceviriler/{dil}.ts'; s = oku(p)
    m = re.search(r"    birlikte: '[^']*',\n", s); assert m, dil
    s = s.replace(m.group(0), f"    checkInYapti: '{c}',\n    ileBirlikte: '{b}',\n", 1)
    yaz(p, s)

# ---------------- kart ----------------
p = 'src/tasarim/CheckInKarti.tsx'; s = oku(p)
def rep(a, b):
    global s
    assert a in s, a[:70]; s = s.replace(a, b, 1)

rep("""import { suAnBuradaMi } from '../../lib/zaman'
""", """import { suAnBuradaMi } from '../../lib/zaman'
import { bulunmaEki } from '../../lib/bulunma-eki'
import { useDil as useDilBilgisi } from '../../lib/dil'
""")

# baslik cumlesi + zaman
rep("""        <View style={stiller.orta}>
          <Text
            style={stiller.kullaniciAdi}
            numberOfLines={1}
            onPress={() => router.push(kisiYolu as never)}
          >
            {gosterilenAd}
          </Text>
          {suAnBuradaMi(oge.olusturmaZamani, oge.canliMi) ? (""", """        <View style={stiller.orta}>
          {/* BASLIK TEK CUMLE (kullanicinin referansi 2026-09-20):
              "<ad>, <mekan>'de check-in yapti." - ad kalin siyah
              (profil), mekan kalin turuncu (harita), ek ve fiil duz.
              Sablon sozlukte; parcalar {{ad}}/{{mekan}}/{{ek}}
              belirteclerinden bolunerek ic ice Text'le ciziliyor. Ek
              yalnizca Turkce'de (`bulunmaEki`), digerlerinde bos. */}
          <Text style={stiller.baslik} testID="akis-basligi">
            {basligiCiz()}
          </Text>
          {suAnBuradaMi(oge.olusturmaZamani, oge.canliMi) ? (""")

# mekan satiri kalkti, birlikte satiri yeniden
i = s.index("""      {/* MEKAN SATIRI: igne + ad, turuncu ve basilabilir.""")
j = s.index("""      {/* NOT ONCE, FOTOGRAF ALTINDA (kullanicinin istegi 2026-08-30). */}""")
s = s[:i] + """      {/* "<adlar> ile birlikte" (referans): kucuk avatarlar + kullanici
          adlari kalin, geri kalan gri; metin sutunuyla hizali. Her
          avatar/ad o kisinin profiline gider. */}
      {oge.etiketler.length > 0 && (
        <View style={stiller.birlikteSatiri} testID="birlikte-satiri">
          <View style={stiller.birlikteAvatarlar}>
            {oge.etiketler.slice(0, 3).map((etiket, i) => (
              <Pressable
                key={etiket.kullaniciId}
                onPress={() => router.push(`/kullanici/${etiket.kullaniciId}`)}
                accessibilityRole="button"
                accessibilityLabel={etiket.kullaniciAdi ?? etiket.ad ?? ''}
                hitSlop={4}
                testID={`birlikte-${etiket.kullaniciId}`}
                style={i > 0 && stiller.birlikteAvatarUstUste}
              >
                <Avatar
                  fotografUrl={etiket.avatarUrl}
                  ad={etiket.ad}
                  kullaniciAdi={etiket.kullaniciAdi ?? etiket.ad ?? ''}
                  cap={ETIKET_AVATAR_CAPI}
                />
              </Pressable>
            ))}
          </View>
          <Text style={stiller.birlikteYazi} numberOfLines={2}>
            {ileBirlikteCiz()}
          </Text>
        </View>
      )}

""" + s[j:]

# yardimci cizim islevleri: return'den once
rep("""  const gosterilenAd = oge.rumuz ?? oge.kullaniciAdi ?? ''

  return (""", """  const gosterilenAd = oge.rumuz ?? oge.kullaniciAdi ?? ''
  const { dil } = useDilBilgisi()

  /** Sablonu belirteclerden bolup ic ice Text uretir. */
  function basligiCiz() {
    const ek = dil === 'tr' ? bulunmaEki(oge.mekanAdi) : ''
    const sablon = t('anaSayfa.checkInYapti')
    return sablon.split(/(\\{\\{ad\\}\\}|\\{\\{mekan\\}\\}|\\{\\{ek\\}\\})/).map((parca, i) => {
      if (parca === '{{ad}}')
        return (
          <Text key={i} style={stiller.baslikAd} onPress={() => router.push(kisiYolu as never)}>
            {gosterilenAd}
          </Text>
        )
      if (parca === '{{mekan}}')
        return (
          <Text
            key={i}
            style={stiller.baslikMekan}
            accessibilityRole="link"
            accessibilityLabel={t('anaSayfa.haritadaGor', { ad: oge.mekanAdi })}
            onPress={() => router.push(`/harita/${oge.mekanId}` as never)}
          >
            {oge.mekanAdi}
          </Text>
        )
      if (parca === '{{ek}}') return <Text key={i}>{ek}</Text>
      return <Text key={i}>{parca}</Text>
    })
  }

  function ileBirlikteCiz() {
    const sablon = t('anaSayfa.ileBirlikte')
    const adlar = oge.etiketler.map((e) => e.kullaniciAdi ?? e.ad ?? '')
    return sablon.split(/(\\{\\{adlar\\}\\})/).map((parca, i) =>
      parca === '{{adlar}}' ? (
        <Text key={i}>
          {oge.etiketler.map((e, k) => (
            <Text key={e.kullaniciId}>
              {k > 0 ? ', ' : ''}
              <Text style={stiller.birlikteAd} onPress={() => router.push(`/kullanici/${e.kullaniciId}`)}>
                {adlar[k]}
              </Text>
            </Text>
          ))}
