import re
def oku(p): return open(p, encoding='utf-8').read()
def yaz(p, s): open(p, 'w', encoding='utf-8', newline='\n').write(s)

# ---------- sozluk ----------
S = {
 'tr': ('AKTİF CHECK-IN', 'Mesafe'), 'en': ('ACTIVE CHECK-IN', 'Distance'), 'de': ('AKTIVER CHECK-IN', 'Entfernung'),
 'es': ('CHECK-IN ACTIVO', 'Distancia'), 'fr': ('CHECK-IN ACTIF', 'Distance'), 'ru': ('АКТИВНЫЙ ЧЕК-ИН', 'Расстояние'),
 'ar': ('تسجيل وصول نشط', 'المسافة'),
}
for dil, (a, m) in S.items():
    p = f'lib/ceviriler/{dil}.ts'; s = oku(p)
    i = s.index('  kesfet: {\n')
    mm = re.search(r"    mesafeyeGore: .*\n", s[i:]); assert mm, dil
    s = s[:i] + s[i:].replace(mm.group(0), mm.group(0) + f"    mesafe: '{m}',\n    aktifCheckIn: '{a}',\n", 1)
    yaz(p, s)

# ---------- ekran ----------
p = 'src/app/mekanlar/index.tsx'; s = oku(p)
def rep(a, b):
    global s
    assert a in s, a[:70]; s = s.replace(a, b, 1)

# AKTIF CHECK-IN KARTI
i = s.index("  const buradaKarti = kartMekani && (")
j = s.index("  /** Arama kutusu + tur suzgeci + oneriler + secili tur cipleri + durum cipleri. */")
s = s[:i] + """  const buradaKarti = kartMekani && (
    /* AKTIF CHECK-IN KARTI (kullanicinin referansi 2026-09-20 aksam):
       seftali zemin, solda igne, "AKTIF CHECK-IN" etiketi, ad, ilce/il;
       altta "N kisi burada >" (mekan sayfasi) ve beyaz "Ayrildim" hapi;
       sag ustte uc nokta -> Sil (onaylı). 2026-09-19'un buyuk sayi +
       "Su an buradasin" seridi bu referansla kalkti. */
    <View style={stiller.buradaKart} testID="burada-karti">
      <View style={stiller.buradaUst}>
        <View style={stiller.buradaIgne}>
          <IgneIkonu boyut={24} />
        </View>
        <Pressable
          style={stiller.buradaMetin}
          onPress={() => router.push(`/harita/${kartMekani.id}` as never)}
          accessibilityRole="button"
          accessibilityLabel={t('kesfet.konumuAc', { ad: kartMekani.ad })}
        >
